// P0.3 — resolve the runtime client scope FIRST. The supervised webhook POST
// body arrives under $json.body in n8n; fall back to direct fields for
// programmatic calls. Emits both clientId and clientCode (empty string when
// not supplied); the downstream 'Resolve client' node fills the missing one
// from the clients table so no SQL node ever sees an undefined :clientId.
const src = ($json && $json.body && typeof $json.body === 'object') ? $json.body : $json;
const clientId = (src && src.clientId) ? String(src.clientId) : '';
const clientCode = (src && src.clientCode) ? String(src.clientCode) : '';
return { json: { clientId: clientId, clientCode: clientCode } };

// Merge the extractor response with the raw-doc + client scope so the ingest
// node has every parameter it needs (documentId, clientId, clientCode). The
// HTTP node only forwards the service response; we re-attach the runtime scope.
const res = $json || {};
const scope = $node['Resolve client'].json || {};
const rawDocs = $('Load raw PDF/URL Truth docs').all().map(function(it){ return it.json; });
const byUri = {};
for (const d of rawDocs) if (d.source_uri) byUri[d.source_uri] = d;
const doc = byUri[res.source_uri] || rawDocs[0] || {};
return { json: {
  text: res.text, parser: res.parser, checksum: res.checksum,
  source_uri: res.source_uri, chars: res.chars, ok: res.ok,
  clientId: scope.clientId, clientCode: scope.clientCode,
  documentId: doc.documentId, importKey: doc.import_key
} };

// Build a single extraction prompt from all received Truth docs with content.
// The LLM extracts claims from the ACTUAL content, never from metadata alone.
const scope = $node['Resolve client'].json;
const clientCode = scope.clientCode;
const clientId = scope.clientId;
const docs = $('Load content Truth docs').all().map(function(it){ return it.json; });
const list = docs.map(function(d){
  return '- doc[' + (d.import_key || '') + '] type=' + (d.documentType || '') +
  '\n  title=' + (d.title || '') + ' uri=' + (d.source_uri || '') +
  '\n  content: ' + (d.content || '(unavailable)');
}).join('\n');
const prompt =
  'You extract canonical facts from client-provided truth documents. ' +
  'Extract claims ONLY from the content shown below; do not invent facts absent from it.\n' +
  'Return STRICT JSON only, shape:\n' +
  '{"documents":[],' +
  '"entities":[{"entity_type","canonical_name","aliases":[]}],' +
  '"claims":[{"entity_name","field_key","claim_text","document_key","import_key"}]}\n' +
  'Every claim carries document_key = the import_key of the doc it came from, ' +
  'and a deterministic import_key like "SYNTH-<document_key>-<n>".\n\n' +
  'DOCUMENTS:\n' + (list || '(none)') + '\n\nJSON: ';
return { json: { clientId: clientId, clientCode: clientCode, prompt: prompt } };

// Parse the Ollama JSON response into import_truth_pack() inputs. P0.1:
// evidence must bind claim -> truth_document -> locator. document_key is
// resolved against the loaded docs' REAL import_key, and evidence_locator
// carries the authoritative truth_documents.id (document_id).
const scope = $node['Resolve client'].json;
const clientCode = scope.clientCode;
const clientId = scope.clientId;
const raw = $json.response || '';
let data = {};
if (typeof raw === 'string') { try { data = JSON.parse(raw); } catch (e) { data = {}; } }
else if (raw && typeof raw === 'object') data = raw;
const docs = Array.isArray(data.documents) ? data.documents : [];

// Normalize entities: small models may echo the schema field names verbatim.
const ents = Array.isArray(data.entities) ? data.entities : [];
const entities = [];
for (const e of ents) {
  if (!e || typeof e !== 'object' || e.claim) continue;
  const canonical = e.canonical_name || e.entity_name;
  if (!canonical) continue;
  const etype = (e.entity_type && e.entity_type !== 'canonical_name') ? e.entity_type : 'COMPANY';
  entities.push({
    entity_type: etype,
    canonical_name: canonical,
    aliases: Array.isArray(e.aliases) ? e.aliases : []
  });
}

// Resolve each claim's document_key to the REAL truth_documents.id. No import_key
// prefix guessing: the LLM must declare document_key explicitly, and we look up
// that import_key against the loaded docs (same client only).
const loaded = $('Load content Truth docs').all().map(function(it){ return it.json; });
const byKey = {};
for (const d of loaded) byKey[d.import_key] = d;
const claims = Array.isArray(data.claims) ? data.claims : [];
const claimsOut = claims.map(function(c){
  if (!c || typeof c !== 'object') return c;
  const dk = c.document_key || '';
  const src = byKey[dk];
  const loc = {
    document_id: src ? src.documentId : null,
    page: null,
    section: null,
    table_ref: null,
    row_ref: null,
    source_uri: src ? src.source_uri : null,
    excerpt: (c.claim_text || '').slice(0, 500)
  };
  c.document_key = dk;
  c.evidence_locator = loc;
  return c;
});
return {
  json: {
    clientId: clientId,
    clientCode: clientCode,
    pDocs: JSON.stringify(docs),
    pEntities: JSON.stringify(entities),
    pClaims: JSON.stringify(claimsOut)
  }
};
